  const q=useListSkills(params);const create=useCreateSkill();const update=useUpdateSkill();const del=useDeleteSkill();const qc=useQueryClient();
  const refresh=()=>{void qc.invalidateQueries({queryKey:getListSkillsQueryKey()});void qc.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()});};
  const submit=(d:SkillInput)=>{const onSuccess=()=>{refresh();setShow(false);setEditing(null);setNotice('Skill saved.');toast({title:'Skill saved',description:'Your growth map has been updated.'});};if(editing)update.mutate({id:editing.id,data:d},{onSuccess,onError:(e:any)=>{setNotice(friendlyError(e));toast({title:'Could not save skill',description:friendlyError(e),variant:'destructive'});}});else create.mutate({data:d},{onSuccess,onError:(e:any)=>{setNotice(friendlyError(e));toast({title:'Could not save skill',description:friendlyError(e),variant:'destructive'});}});};
