    {notice&&<div role="status" style={{marginBottom:12,padding:10,background:'#f0efff',color:'#5149b8',borderRadius:7,fontSize:11}}>{notice}</div>}
    <section className="panel" style={{padding:0}}><div className="toolbar"><label className="search-box"><Search size={15}/><input aria-label="Search skills" placeholder="Search skills…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select className="select" aria-label="Filter by category" value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option>{cats.map(c=><option value={c} key={c}>{c}</option>)}</select></div>
      {skills.length?<div className="table-wrap"><table><thead><tr><th>Skill</th><th>Category</th><th>Current</th><th>Target</th><th>Progress to target</th><th></th></tr></thead><tbody>{skills.map((s:any)=><tr key={s.id}><td className="table-primary">{s.name}</td><td>{s.category}</td><td>{s.proficiencyLevel} / 5</td><td>{s.targetLevel} / 5</td><td style={{minWidth:160}}><div className="progress"><span style={{width:`${Math.min(100,Math.round(s.proficiencyLevel/Math.max(1,s.targetLevel)*100))}%`}}/></div></td><td><div className="table-actions"><button className="icon-btn" aria-label={`Edit ${s.name}`} onClick={()=>{setEditing(s);setShow(true)}}><Pencil size={13}/></button><button className="icon-btn" aria-label={`Delete ${s.name}`} onClick={()=>remove(s)}><Trash2 size={13}/></button></div></td></tr>)}</tbody></table></div>:<Empty icon={Target} title={search||category?'No skills found':'Choose what you want to grow'} description={search||category?'Try adjusting your filters.':'Add the skills you’re building and define a realistic next target.'} action={<button className="btn btn-primary" onClick={()=>setShow(true)}><Plus size={14}/> Add a skill</button>}/>}</section>
    {show&&<Modal title={editing?'Edit skill':'Add a skill'} onClose={()=>setShow(false)}><SkillForm item={editing} pending={create.isPending||update.isPending} onCancel={()=>setShow(false)} onSubmit={submit}/></Modal>}
