function SkillForm({item,pending,onSubmit,onCancel}:{item:Skill|null;pending:boolean;onSubmit:(d:SkillInput)=>void;onCancel:()=>void}) {
  const [name,setName]=useState(item?.name||'');const [category,setCategory]=useState(item?.category||'');const [proficiency,setProficiency]=useState(item?.proficiencyLevel||1);const [target,setTarget]=useState(item?.targetLevel||3);const [error,setError]=useState('');
  return <form onSubmit={e=>{e.preventDefault();if(!name.trim()||!category.trim()){setError('Skill name and category are required.');return;}onSubmit({name:name.trim(),category:category.trim(),proficiencyLevel:Number(proficiency),targetLevel:Number(target)});}}><div className="form-grid"><Field label="Skill name"><input value={name} onChange={e=>setName(e.target.value)} maxLength={100} placeholder="e.g. System design" required/></Field><Field label="Category"><input value={category} onChange={e=>setCategory(e.target.value)} maxLength={80} placeholder="e.g. Backend" required/></Field><Field label="Current level"><select value={proficiency} onChange={e=>setProficiency(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option key={x} value={x}>{x} — {['Exploring','Learning','Practicing','Confident','Advanced'][x-1]}</option>)}</select></Field><Field label="Target level"><select value={target} onChange={e=>setTarget(Number(e.target.value))}>{[1,2,3,4,5].map(x=><option key={x} value={x}>{x} — {['Exploring','Learning','Practicing','Confident','Advanced'][x-1]}</option>)}</select></Field></div>{error&&<p className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="btn btn-secondary" onClick={onCancel}>Cancel</button><button className="btn btn-primary" disabled={pending}>{pending?'Saving…':'Save skill'}</button></div></form>;
}
function Analytics() {return <Protected><AnalyticsContent/></Protected>}
function AnalyticsContent() {
  const dsa=useGetDsaAnalytics({query:{queryKey:getGetDsaAnalyticsQueryKey()}});
  const activity=useGetActivityAnalytics({days:90},{query:{queryKey:getGetActivityAnalyticsQueryKey({days:90})}});
  if(dsa.isLoading||activity.isLoading)return <LoadBlock/>;if(dsa.isError||activity.isError)return <div className="page"><ErrorState error={dsa.error||activity.error} retry={()=>{void dsa.refetch();void activity.refetch()}}/></div>;
  if(!dsa.data||!activity.data)return <div className="page"><ErrorState retry={()=>{void dsa.refetch();void activity.refetch()}}/></div>;const dist=dsa.data.difficultyDistribution||[];const topics=dsa.data.topicProgress||[];const days=activity.data||[];const max=Math.max(...days.map(x=>x.count),1);const total=days.reduce((a,x)=>a+x.count,0);const colors=['#5aa487','#e4a849','#dc7270'];
  return <main className="page"><PageHeading kicker="Reflection" title="Analytics" description="Use your own activity to notice patterns, celebrate progress, and choose what comes next."/>
    <div className="metric-grid" style={{gridTemplateColumns:'repeat(2,minmax(0,1fr))'}}><div className="metric"><div className="metric-label"><Activity size={14}/>Logged activity · 90 days</div><div className="metric-value">{total}</div><div className="metric-foot">Recorded actions across your workspace</div></div><div className="metric"><div className="metric-label"><Trophy size={14}/>Topics practiced</div><div className="metric-value">{topics.length}</div><div className="metric-foot">Distinct DSA topics in your log</div></div></div>
    <div className="analytics-grid"><section className="panel"><div className="section-head"><div><h2 className="panel-title">Difficulty distribution</h2><p className="panel-subtitle">Solved problems across your practice log</p></div></div>{dist.length?<div className="donut-wrap"><div className="donut" style={{background:`conic-gradient(${dist.map((x:any,i:number)=>`${colors[i%3]} ${dist.slice(0,i).reduce((a:any,y:any)=>a+(y.solved||0),0)/Math.max(1,dist.reduce((a:any,y:any)=>a+y.solved,0))*100}% ${(dist.slice(0,i+1).reduce((a:any,y:any)=>a+(y.solved||0),0))/Math.max(1,dist.reduce((a:any,y:any)=>a+y.solved,0))*100}%`).join(',')})`}}><div className="donut-hole">{dist.reduce((a:any,x:any)=>a+x.solved,0)}<small style={{font:'500 9px DM Sans',color:'#9299a7'}}>solved</small></div></div><div className="legend">{dist.map((x:any,i:number)=><div className="legend-line" key={x.difficulty}><span className="legend-dot" style={{background:colors[i%3]}}/>{statusLabel(x.difficulty)}<strong style={{marginLeft:'auto',color:'#333d52'}}>{x.solved} / {x.total}</strong></div>)}</div></div>:<Empty icon={Code2} title="No difficulty data yet" description="Log DSA problems to see how your practice is distributed."/>}</section>
      <section className="panel"><div className="section-head"><div><h2 className="panel-title">Topic progress</h2><p className="panel-subtitle">Solved problems by topic</p></div></div>{topics.length?topics.slice(0,8).map((t:any)=><div className="topic-row" key={t.topic}><span>{t.topic}</span><div className="progress"><span style={{width:`${t.total?Math.min(100,t.solved/t.total*100):0}%`}}/></div><span style={{textAlign:'right'}}>{t.solved}/{t.total}</span></div>):<Empty icon={Layers3} title="Topics will take shape" description="Add problems with topics to see where you’ve built strength."/>}</section>
      <section className="panel" style={{gridColumn:'1/-1'}}><div className="section-head"><div><h2 className="panel-title">Activity over time</h2><p className="panel-subtitle">Daily activity for the last 90 days</p></div><span className="badge badge-in-progress">{total} recorded actions</span></div>{days.length?<div className="activity-heatmap">{days.map((day:any)=><div key={day.date} title={`${day.date}: ${day.count} actions`} className="heat-cell" style={{background:day.count?`rgba(105,95,216,${Math.min(.95,.16+day.count/max*.78)})`:'#f0f1f5'}}/> )}</div>:<Empty icon={Activity} title="No activity recorded yet" description="When you start logging career-building work, your rhythm will appear here."/>}</section>
    </div></main>;
}
function SettingsPage() {
  const navigate=useNavigate();const qc=useQueryClient();const userQ=useGetCurrentUser({query:{queryKey:getGetCurrentUserQueryKey()}});const signout=useLogout();const [message,setMessage]=useState('');
  if(userQ.isLoading)return <ProtectedLoading/>;if(userQ.isError)return <div className="page"><ErrorState error={userQ.error} retry={()=>userQ.refetch()}/></div>;
  if(!userQ.data)return <div className="page"><ErrorState retry={()=>userQ.refetch()}/></div>;const user=userQ.data;
  return <main className="page"><PageHeading kicker="Account" title="Settings" description="Your identity and session details for this DevTrack workspace."/><div className="dashboard-grid" style={{gridTemplateColumns:'minmax(0,1.2fr) minmax(250px,.8fr)'}}><section className="panel"><div className="section-head"><div><h2 className="panel-title">Profile details</h2><p className="panel-subtitle">Your account information</p></div></div><div className="profile-detail"><span className="avatar" style={{width:48,height:48,fontSize:16}}>{user.name.split(/\s+/).map((x:string)=>x[0]).slice(0,2).join('').toUpperCase()}</span><div><strong>{user.name}</strong><div className="subtitle">{user.email}</div></div></div><div className="settings-row"><div><span className="settings-label">Name</span><strong>{user.name}</strong></div></div><div className="settings-row"><div><span className="settings-label">Email address</span><strong>{user.email}</strong></div></div><div className="settings-row"><div><span className="settings-label">Member since</span><strong>{new Date(user.createdAt).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}</strong></div></div>{message&&<p role="status" className="form-error">{message}</p>}</section><section className="panel"><div className="section-head"><div><h2 className="panel-title">Session</h2><p className="panel-subtitle">Manage access to this device</p></div></div><div style={{background:'#f7f7fc',borderRadius:8,padding:15,marginBottom:18}}><div style={{fontSize:12,fontWeight:700,color:'#374158',marginBottom:5}}>You’re signed in</div><p className="subtitle">Your records are attached to this account and are not visible to other users.</p></div><button className="btn btn-danger" disabled={signout.isPending} onClick={()=>signout.mutate(undefined,{onSuccess:()=>{qc.clear();navigate('/');},onError:(e:any)=>setMessage(friendlyError(e))})}><LogOut size={14}/>{signout.isPending?'Signing out…':'Sign out'}</button></section></div></main>;
}
function NotFound() {
  const path=useLocation().pathname;return <main className="landing" style={{minHeight:'100dvh'}}><header className="landing-nav"><Link href="/" className="landing-brand"><span className="brand-mark"><Code2 size={18}/></span>devtrack</Link><Link href="/" className="btn btn-secondary">Back to home</Link></header><section className="state-card"><div className="eyebrow">404 · route not found</div><h1 style={{fontSize:50}}>This path isn’t on the map.</h1><p>We couldn’t find <code>{path}</code>. Head back to your starting point.</p><Link href="/" className="btn btn-primary">Return home <ArrowRight size={14}/></Link></section></main>;
}
export default App;
